import Page11 from './pages/Page11.jsx';
const pages={"demo-analytics-1":Page0,"demo-analytics-1-about":Page1,"demo-analytics-1-analyst":Page2,"demo-analytics-1-changelog":Page3,"demo-analytics-1-contact":Page4,"demo-analytics-1-customer-story":Page5,"demo-analytics-1-customers":Page6,"demo-analytics-1-feature":Page7,"demo-analytics-1-integrations":Page8,"demo-analytics-1-pricing":Page9,"demo-analytics-1-product":Page10,"demo-analytics-1-solutions":Page11};
export default function App(){
const [page,setPage]=useState(()=>new URLSearchParams(location.hash.slice(1)).get('page')||"demo-analytics-1");
useEffect(()=>{const change=()=>setPage(new URLSearchParams(location.hash.slice(1)).get('page')||"demo-analytics-1");const navigate=e=>{const a=e.target.closest('a[href]');const href=a?.getAttribute('href');if(!href?.startsWith('#page='))return;const next=new URLSearchParams(href.slice(1)).get('page');if(!pages[next])return;e.preventDefault();e.stopPropagation();setPage(next);try{if(location.protocol!=='about:')history.pushState(null,'',href)}catch{}};document.addEventListener('click',navigate,true);window.addEventListener('hashchange',change);window.addEventListener('popstate',change);return()=>{document.removeEventListener('click',navigate,true);window.removeEventListener('hashchange',change);window.removeEventListener('popstate',change)}},[]);
useTemplateRuntime(page);const Page=pages[page]||Page0;return <div id='template-page' key={page}><Page/></div>;
}

